using System.ComponentModel.DataAnnotations;

namespace sv_424fc73418d24375be1263c3a9e16100.Models;

public class AppointmentFormModel
{
    // Step 1
    [Required(ErrorMessage = "Patient name is required.")]
    public string PatientName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Email is required.")]
    [EmailAddress(ErrorMessage = "Invalid email format.")]
    public string Email { get; set; } = string.Empty;

    [Required(ErrorMessage = "Phone number is required.")]
    public string Phone { get; set; } = string.Empty;

    [Required(ErrorMessage = "Insurance provider is required.")]
    public string InsuranceProvider { get; set; } = string.Empty;

    // Step 2
    [Required(ErrorMessage = "Please select a doctor.")]
    public string Doctor { get; set; } = string.Empty;

    [Required(ErrorMessage = "Date is required.")]
    public DateOnly? AppointmentDate { get; set; }

    [Required(ErrorMessage = "Please select a time slot.")]
    public string TimeSlot { get; set; } = string.Empty;

    [Required(ErrorMessage = "Reason for visit is required.")]
    [MaxLength(500, ErrorMessage = "Reason cannot exceed 500 characters.")]
    public string ReasonForVisit { get; set; } = string.Empty;
}

public class PatientValidationResult
{
    public bool IsValid => Errors.Count == 0;
    public Dictionary<string, string> Errors { get; set; } = new();
}

using sv_424fc73418d24375be1263c3a9e16100.Models;

namespace sv_424fc73418d24375be1263c3a9e16100.Services;

public class AppointmentService
{
    private static readonly List<string> Doctors =
        ["Dr. Smith", "Dr. Johnson", "Dr. Williams", "Dr. Brown"];

    private static readonly List<string> AllTimeSlots =
        ["9:00 AM", "9:30 AM", "10:00 AM", "10:30 AM", "11:00 AM",
         "1:00 PM", "1:30 PM", "2:00 PM", "2:30 PM", "3:00 PM"];

    public Task<List<string>> GetDoctorsAsync()
    {
        return Task.FromResult(new List<string>(Doctors));
    }

    public Task<List<string>> GetAvailableSlotsAsync(string doctor, DateOnly date)
    {
        // Stub: return all slots regardless of doctor/date
        return Task.FromResult(new List<string>(AllTimeSlots));
    }

    public Task<PatientValidationResult> ValidatePatientAsync(AppointmentFormModel model)
    {
        var result = new PatientValidationResult();

        // Reject "taken@example.com" for outstanding balance
        if (string.Equals(model.Email, "taken@example.com", StringComparison.OrdinalIgnoreCase))
        {
            result.Errors[nameof(model.Email)] = "Account has outstanding balance.";
        }

        // Reject "None" insurance with Dr. Smith
        if (model.InsuranceProvider == "None"
            && string.Equals(model.Doctor, "Dr. Smith", StringComparison.OrdinalIgnoreCase))
        {
            result.Errors[nameof(model.Doctor)] = "Selected doctor does not accept self-pay patients.";
        }

        // Reject 10:00 AM slot as taken (race condition simulation)
        if (model.TimeSlot == "10:00 AM")
        {
            result.Errors[nameof(model.TimeSlot)] = "This slot is no longer available.";
        }

        return Task.FromResult(result);
    }
}

@page "/book-appointment"
@rendermode InteractiveServer
@using sv_424fc73418d24375be1263c3a9e16100.Models
@using sv_424fc73418d24375be1263c3a9e16100.Services
@inject AppointmentService AppointmentService

<PageTitle>Book Appointment</PageTitle>

<h3>Book a Medical Appointment</h3>

<EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="bookAppointment">
    <DataAnnotationsValidator />

    @* ── STEP 1 ── *@
    <fieldset>
        <legend>Patient Information</legend>

        <div class="mb-3">
            <label class="form-label" for="patientName">Patient Name</label>
            <InputText id="patientName" class="form-control" @bind-Value="Model.PatientName" />
            <ValidationMessage For="() => Model.PatientName" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="email">Email</label>
            <InputText id="email" class="form-control" @bind-Value="Model.Email" />
            <ValidationMessage For="() => Model.Email" />
            @if (serverErrors.ContainsKey(nameof(Model.Email)))
            {
                <div class="validation-message">@serverErrors[nameof(Model.Email)]</div>
            }
        </div>

        <div class="mb-3">
            <label class="form-label" for="phone">Phone</label>
            <InputText id="phone" class="form-control" @bind-Value="Model.Phone" />
            <ValidationMessage For="() => Model.Phone" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="insurance">Insurance Provider</label>
            <InputSelect id="insurance" class="form-select" @bind-Value="Model.InsuranceProvider">
                <option value="">-- Select --</option>
                <option value="Aetna">Aetna</option>
                <option value="BlueCross">BlueCross</option>
                <option value="Cigna">Cigna</option>
                <option value="UnitedHealth">UnitedHealth</option>
                <option value="None">None</option>
            </InputSelect>
            <ValidationMessage For="() => Model.InsuranceProvider" />
        </div>

        @if (!showStep2)
        {
            <button type="button" class="btn btn-primary" @onclick="ProceedToStep2">
                Next
            </button>
        }
    </fieldset>

    @* ── STEP 2 ── *@
    @if (showStep2)
    {
        <fieldset class="mt-4">
            <legend>Appointment Details</legend>

            <div class="mb-3">
                <label class="form-label" for="doctor">Preferred Doctor</label>
                <InputSelect id="doctor" class="form-select" @bind-Value="Model.Doctor"
                             @bind-Value:after="OnDoctorOrDateChanged">
                    <option value="">-- Select --</option>
                    @foreach (var doc in doctors)
                    {
                        <option value="@doc">@doc</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.Doctor" />
                @if (serverErrors.ContainsKey(nameof(Model.Doctor)))
                {
                    <div class="validation-message">@serverErrors[nameof(Model.Doctor)]</div>
                }
            </div>

            <div class="mb-3">
                <label class="form-label" for="date">Appointment Date</label>
                <InputDate id="date" class="form-control" @bind-Value="Model.AppointmentDate"
                           @bind-Value:after="OnDoctorOrDateChanged" />
                <ValidationMessage For="() => Model.AppointmentDate" />
                @if (Model.AppointmentDate.HasValue && Model.AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today))
                {
                    <div class="validation-message">Date must be in the future.</div>
                }
            </div>

            <div class="mb-3">
                <label class="form-label" for="timeSlot">Time Slot</label>
                <InputSelect id="timeSlot" class="form-select" @bind-Value="Model.TimeSlot">
                    <option value="">-- Select --</option>
                    @foreach (var slot in availableSlots)
                    {
                        <option value="@slot">@slot</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.TimeSlot" />
                @if (serverErrors.ContainsKey(nameof(Model.TimeSlot)))
                {
                    <div class="validation-message">@serverErrors[nameof(Model.TimeSlot)]</div>
                }
            </div>

            <div class="mb-3">
                <label class="form-label" for="reason">Reason for Visit</label>
                <InputTextArea id="reason" class="form-control" @bind-Value="Model.ReasonForVisit" rows="3" />
                <ValidationMessage For="() => Model.ReasonForVisit" />
            </div>

            <button type="button" class="btn btn-secondary me-2" @onclick="BackToStep1">
                Back
            </button>
            <button type="button" class="btn btn-info me-2" @onclick="CheckAvailability">
                Check Availability
            </button>
            <button type="submit" class="btn btn-success" disabled="@(!isAvailabilityChecked)">
                Book Appointment
            </button>
        </fieldset>
    }

    @if (isSubmitted)
    {
        <div class="alert alert-success mt-3">
            Appointment booked successfully!
        </div>
    }
</EditForm>

@code {
    private AppointmentFormModel Model { get; set; } = new();
    private bool showStep2;
    private bool isSubmitted;
    private bool isAvailabilityChecked;
    private List<string> doctors = new();
    private List<string> availableSlots = new();
    private Dictionary<string, string> serverErrors = new();

    private readonly string[] step1Fields =
        [nameof(AppointmentFormModel.PatientName), nameof(AppointmentFormModel.Email),
         nameof(AppointmentFormModel.Phone), nameof(AppointmentFormModel.InsuranceProvider)];

    protected override async Task OnInitializedAsync()
    {
        doctors = await AppointmentService.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        // Validate step 1 fields manually
        var context = new ValidationContext(Model);
        var results = new List<ValidationResult>();
        Validator.TryValidateObject(Model, context, results, true);

        var step1Errors = results.Where(r =>
            r.MemberNames.Any(m => step1Fields.Contains(m))).ToList();

        if (step1Errors.Count == 0)
        {
            showStep2 = true;
        }
    }

    private void BackToStep1()
    {
        showStep2 = false;
        serverErrors.Clear();
        isAvailabilityChecked = false;
    }

    private async Task OnDoctorOrDateChanged()
    {
        serverErrors.Clear();
        isAvailabilityChecked = false;

        if (!string.IsNullOrEmpty(Model.Doctor) && Model.AppointmentDate.HasValue)
        {
            availableSlots = await AppointmentService.GetAvailableSlotsAsync(
                Model.Doctor, Model.AppointmentDate.Value);
            Model.TimeSlot = string.Empty;
        }
    }

    private async Task CheckAvailability()
    {
        serverErrors.Clear();
        isAvailabilityChecked = false;

        // Client-side: date must be in the future
        if (Model.AppointmentDate.HasValue
            && Model.AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today))
        {
            return;
        }

        // Validate step 2 required fields
        var context = new ValidationContext(Model);
        var results = new List<ValidationResult>();
        Validator.TryValidateObject(Model, context, results, true);

        var step2Fields = new[]
        {
            nameof(AppointmentFormModel.Doctor), nameof(AppointmentFormModel.AppointmentDate),
            nameof(AppointmentFormModel.TimeSlot), nameof(AppointmentFormModel.ReasonForVisit)
        };
        var step2Errors = results.Where(r =>
            r.MemberNames.Any(m => step2Fields.Contains(m))).ToList();

        if (step2Errors.Count > 0)
        {
            return;
        }

        var validationResult = await AppointmentService.ValidatePatientAsync(Model);

        if (!validationResult.IsValid)
        {
            foreach (var error in validationResult.Errors)
            {
                serverErrors[error.Key] = error.Value;
            }
            return;
        }

        isAvailabilityChecked = true;
    }

    private async Task HandleSubmit()
    {
        if (!isAvailabilityChecked)
        {
            return;
        }

        // Final server-side validation before booking
        var validationResult = await AppointmentService.ValidatePatientAsync(Model);
        if (!validationResult.IsValid)
        {
            serverErrors.Clear();
            foreach (var error in validationResult.Errors)
            {
                serverErrors[error.Key] = error.Value;
            }
            isAvailabilityChecked = false;
            return;
        }

        isSubmitted = true;
    }
}

